/* 도로주행 -- 배경 도로 PNG (base64 내장, sprites-data.js와 동일 방식).
 * file:// 환경에서 상대경로 <img>는 그려지긴 하지만 canvas가 tainted되어(getImageData 불가)
 * 결과화면 공유/저장(canvas.toBlob)이 깨진다 -- 그래서 주차게임 차량 스프라이트와 같은 방식으로 내장한다. */
(function(){
  "use strict";
  window.DRIVING_ROAD_BG = {
    urban: "data:image/png;base64,",
    residential: "data:image/png;base64,",
    park: "data:image/png;base64,",
    riverside: "data:image/png;base64,",
    mountain: "data:image/png;base64,",
  };
})();
